:root {
  --paper: #fffdf5;
  --ink: #254238;
  --leaf: #4f8a63;
  --mist: #e4f0df;
  --line: #b9d2ba;
}

.conservatory-pass {
  width: 460px;
  box-sizing: border-box;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--leaf);
  border-radius: 18px;
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pass-header > span {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  font-size: 25px;
  background: var(--mist);
  border-radius: 50%;
}

.pass-header p {
  margin: 0 0 2px;
  color: var(--leaf);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.pass-header h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.15;
}

.pass-details {
  display: flex;
  justify-content: space-between;
  margin: 14px 0 10px;
  padding: 10px 0;
  font-size: 14px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
}

.pass-footer button {
  padding: 7px 14px;
  color: var(--paper);
  background: var(--leaf);
  border: 0;
  border-radius: 8px;
  font-weight: 700;
}
